import { chromium } from 'playwright';
const URL='https://www.statesideqm.com/collections/stateside-quartermaster-logo-merch?preview_theme_id=158561894555';
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
const b=await chromium.launch({headless:true});
for(const [name,viewport] of [['desktop',{width:1440,height:1000}],['mobile',{width:390,height:844}]]){const c=await b.newContext({viewport}),p=await c.newPage(),errors=[];p.on('pageerror',e=>errors.push(e.message));let r;for(let i=0;i<3;i++){r=await p.goto(URL,{waitUntil:'domcontentloaded',timeout:45000});if((r?.status()||0)<500)break;await sleep(1500)}try{await p.waitForFunction(()=>document.querySelector('#MainContent')?.dataset.sqRefineV3Ready==='true',{timeout:20000})}catch{}await sleep(6500);const d=await p.evaluate(()=>{const main=document.querySelector('#MainContent'),results=main?.querySelector('.sq-refine-v3-results'),grid=results?.querySelector('.product-grid'),card=results?.querySelector('.product-grid__item,li.grid__item,.product-card-wrapper,.card-wrapper,[data-product-card]');function info(el){if(!el)return null;const s=getComputedStyle(el),r=el.getBoundingClientRect();return{tag:el.tagName,cls:String(el.className||''),display:s.display,width:r.width,gridTemplateColumns:s.gridTemplateColumns,flexBasis:s.flexBasis,maxWidth:s.maxWidth,widthCss:s.width}}const chain=[];let n=card;for(let i=0;i<7&&n;i++,n=n.parentElement)chain.push(info(n));const rr=results?.getBoundingClientRect(),cr=card?.getBoundingClientRect();return{httpReady:main?.dataset.sqRefineV3Ready,cleanup:main?.dataset.sqRefineV3RootCleanup,error:main?.dataset.sqRefineV3Error||'',results:info(results),grid:info(grid),card:info(card),ratio:rr&&cr?cr.width/rr.width:null,chain}});console.log('LOGO_DIAG '+JSON.stringify({name,http:r?.status()||0,errors,data:d},null,2));await c.close()}await b.close();
